export const getCmdLine = (
		cmdName: string,
		lArgs: string[]
		): string => {

	assert(isString(cmdName), `cmdName not a string: ${OL(cmdName)}`)
	assert(isArrayOfStrings(lArgs), `not an array of strings: ${OL(lArgs)}`)
	const cmdLine = `${cmdName} ${lArgs.join(' ')}`
	DBG(`cmdLine = ${OL(cmdLine)}`)
	return cmdLine
}

// ---------------------------------------------------------------------------

export type TStreamType = 'piped' | 'inherit'

export type TExecResult = {
	success: boolean
	notNeeded?: true
	stdout?: string
	stderr?: string
	infile?: string
	outfile?: string
}

// ---------------------------------------------------------------------------
// ASYNC

export const mkstr = (
		item: string | BufferSource
		): string => {

	return (
		  isString(item) ? stripAnsiCode(item)
		: isArray(item)  ? stripAnsiCode(item.join(''))
		:                  stripAnsiCode(decode(item))
		)
}

// ---------------------------------------------------------------------------
// ASYNC
// --- Four cases for stdout:
//        1. no callback, capture false
//           output goes directly to the console
//        2. callback defined
//           output goes to a callback function
//        3. capture is set
//           output is found in the result hash
//        4. callback defined and capture set
//           output both in result hash and goes to callback

type TExecInput = string | string[] | TIterator<string> | TAsyncIterator<string>
type TExecCallback = (str: string) => void

export const execCmd = async (
		cmdName: string,
		lArgs: string[] = [],
		hOptions: hash = {}
		): AutoPromise<TExecResult> => {

	type opt = {
		input: (TExecInput | undefined)
		callback: (TExecCallback | undefined)
		capture: boolean
		infile: (string | undefined)
		outfile: (string | undefined)
		}

	const {input, callback, capture, infile, outfile
			} = getOptions<opt>(hOptions, {
		input: undef,
		callback: undef,
		capture: false,
		infile: undef,
		outfile: undef
		})

	debugger
	DBG(`execCmd: ${getCmdLine(cmdName, lArgs)}`)

	const mustPipe = capture || defined(callback) || defined(outfile)
	if (!mustPipe && notdefined(input)) {
		const cmd = new Deno.Command(cmdName, {
			args: lArgs
			})
		const hResult = await cmd.output()

		const code = hResult.code
		const success = hResult.success
		const stdout = decode(hResult.stdout)
		const stderr = decode(hResult.stderr)
		return {success, stdout, stderr}
	}

	const cmd: Deno.Command = new Deno.Command(cmdName, {
		args: lArgs,
		env: {DEFAULT_LOGGER: curLogLevel()},
		stdin:  defined(input) ? 'piped' : 'inherit',   // --- was 'null'
		stdout: mustPipe || defined(input) ? 'piped' : 'inherit',
		stderr: 'piped'
		})
	const child: Deno.ChildProcess = cmd.spawn()

	if (defined(infile)) {
		assert(notdefined(input), "Can't use both infile and input")
		const contents = await Deno.readTextFile(infile)
		const iter = allLinesIn(contents, {includeNL: true})
		ReadableStream.from(iter)
			.pipeThrough(new TextEncoderStream())
			.pipeTo(child.stdin)
	}
	else if (defined(input)) {
		// --- type of child.stdin is WritableStream<Uint8Array>
		if (isString(input)) {
			const iter = allLinesIn(input, {includeNL: true})
			ReadableStream.from(iter)
				.pipeThrough(new TextEncoderStream())
				.pipeTo(child.stdin)
		}
		else {
			ReadableStream.from(input)
				.pipeThrough(new TextEncoderStream())
				.pipeTo(child.stdin)
		}
	}

	// --- Create a WritableStream that output can be sent to
	// --- type of child.stdout is WritableStream<Uint8Array>

	let stdout: string = ''
	const f = defined(outfile) ? new CWritableFile(outfile) : undef
	const outStrm: WritableStream<string> = (
		(defined(callback)?
			new WritableStream<string>({
				async write(chunk) {
					callback(chunk)
					if (defined(f)) {
						await f.write(chunk)
					}
					if (capture) {
						stdout += chunk
					}
					return
				}
				})
		:
			new WritableStream<string>({
				async write(chunk) {
					stdout += chunk
					if (defined(f)) {
						await f.write(chunk)
					}
					return
				}
				}))
		)

	await (
		child.stdout
		  .pipeThrough(new TextDecoderStream())
		  .pipeTo(outStrm, {preventClose: true})
			)
	const status = await child.status
	return {
		success: status.success,
		stdout,
		stderr: await child.stderr.text(),
		...(infile && {infile}),
		...(outfile && {outfile})
		}
}

// ---------------------------------------------------------------------------

export abstract class CFileHandler {

	abstract get op(): string

	// ..........................................................
	// ASYNC

	async needed(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		return true
	}

	// ..........................................................
	// ASYNC

	abstract handle(
			path: string,
			hOptions: hash
			): Promise<TExecResult>

	// ..........................................................
	// ASYNC

	async handleFile(
			path: string,
			hOptions: hash
			): AutoPromise<TExecResult> {

		const force = ('force' in hOptions) && hOptions.force
		const hResult: TExecResult = (
			  force                         ? await this.handle(path, hOptions)
			: await this.needed(path, hOptions) ? await this.handle(path, hOptions)
			:                                 {success: true, notNeeded: true}
			)
		return Object.assign(hResult, {infile: path})
	}

	// ..........................................................
	// SYNC

	getOutput(hResult: TExecResult): string {

		return (hResult?.stdout || '') + (hResult?.stderr || '')
	}
}

// ---------------------------------------------------------------------------

export const prelog = (
		op: string,
		path: string,
		): void => {

	writeln(`${op} ${toRelPath(path)}`)
	return
}

// ---------------------------------------------------------------------------

export const postlog = (
		success: boolean,
		notNeeded: (boolean | undefined)
		): void => {

	const secs = timer.timeTaken()
	if (success) {
		if (notNeeded) {
			writeln(f`${' - not needed'}:{yellow} (${secs} secs)`)
		}
		else {
			writeln(f`${' - OK'}:{green} (${secs} secs)`)
		}
	}
	else {
		writeln(f`${' - FAILED'}:{red} (${secs} secs)`)
	}
	return
}

