// ASYNC

// --- Later, I want to allow passing multiple TProcSpecs
//     string is a glob pattern

export type TProcSpec = [CFileHandler, lPatterns: string[]]

export const procFiles = async (
		procSpec: TProcSpec,
		hOptions: hash = {}
		): AutoPromise<TExecResult[]> => {

	type opt = {
		quiet: boolean
		verbose: boolean
		serial: boolean
		}
	const {quiet, verbose, serial
		} = getOptions<opt>(hOptions, {
			quiet: false,
			verbose: false,
			serial: false
			})

	assert(!(quiet && verbose), "Can't use both quiet and verbose")
	const [handler, lPatterns] = procSpec
	const {op} = handler
	if (verbose) {
		writeln(`(${op})`)
	}

	const lPaths: string[] = Array.from(allFilesMatching(lPatterns))

	type TResultAccum = [
		TExecResult[],  // --- non-error result of execution
		string[],       //     array of error messages
		string[],       //     array of paths corresponding to non-error exec
		string[]       //     array of paths corresponding to errors
		]

	timer.timeTaken()    // --- this resets the timer

	const lFinalResult: TResultAccum = (
		(await (async ()=>{if (serial) {
			// --- Build an array of functions that return a promise
			const results=[];for (const path of lPaths) {
				results.push(() => handler.handleFile(path, hOptions))
			};const lFunctions =results
			return await awaitAllSerially(lFunctions, lPaths)
		}
		else {
			// --- Build an array of promises
			const results1=[];for (const path of lPaths) {
				results1.push(handler.handleFile(path, hOptions))
			};const lPromises =results1
			return await awaitAll(lPromises, lPaths)
		}})())
		)

	assert(defined(lFinalResult), `Not defined: ${ML(lFinalResult)}`)
	assert(isArray(lFinalResult), `Not an array: ${ML(lFinalResult)}`)
	const [lFulfilled, lRejected, lFulPaths, lRejPaths] = lFinalResult

	const acc0 = [0,0,0]
	const iter = MAP(lFulfilled, acc0, function*(h, acc2) {
		yield h
		const [n1, n2, n3] = acc2
		if (h.success) {
			if (h.notNeeded) {
				return [n1+1, n2, n3]
			}
			else {
				return [n1, n2+1, n3]
			}
		}
		else {
			return [n1, n2, n3+1]
		}
	})

	const [lAllResults, [nNotNeeded, nOk, nErr]] = arrayAndAccumFrom(iter)

	// --- Write results to the console

	let i1 = 0;for (const hResult of lAllResults) {const i = i1++;
		const path = lPaths[i]
		const {success} = hResult
		if (success) {
			if (verbose) {
				showOkResult(handler, path, hResult, hOptions)
			}
		}
		else {
			showErrResult(handler, path, hResult, hOptions)
		}
	}

	let i2 = 0;for (const reason of lRejected) {const i = i2++;
		showRejResult(handler, lRejPaths[i], getErrStr(reason), hOptions)
	}

	if (!quiet || (nOk + nErr > 0)) {
		showFinalResult(op, nNotNeeded, nOk, nErr, lRejected.length, lPatterns, verbose)
	}
	return lFulfilled
}

// ---------------------------------------------------------------------------

let headerPrinted = false

const showFinalResult = (
		op: string,
		notNeeded: number,
		nOk: number,
		nErr: number,
		nRej: number,
		lPatterns: string[],
		verbose: boolean = false
		): void => {

	resetLine()
	if (verbose) {
		return
	}
	if (!headerPrinted) {
		LOG('-'.repeat(46))
		LOG([
			sprintf('%6s', 'secs.'),
			sprintf('%-14s', 'op'),
			sprintf('%3s', 'nnd'),
			sprintf('%3s', 'OK'),
			sprintf('%3s', 'Bad'),
			sprintf('%3s', 'Rej'),
			'file(s)'
		].join(' '))
		LOG('-'.repeat(46))
		headerPrinted = true
	}
	LOG([
		sprintf('%6.2f', timer.timeTaken()),
		sprintf('%-14s', op),
		sprintf('%3d', notNeeded),
		sprintf('%3d', nOk),
		sprintf('%3d', nErr),
		sprintf('%3d', nRej),
		lPatterns.join(' + ')
	].join(' '))
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const procOneFile = async (
		path: string,
		handler: CFileHandler,
		hOptions: hash = {}
		): AutoPromise<TExecResult> => {

	if (!await exists(path)) {
		return {
			success: false,
			stderr: "No such file",
			infile: path
			}
	}
	if ((!('force' in hOptions)) || !hOptions.force) {
		if (!await handler.needed(path)) {
			return {
				success: true,
				notNeeded: true,
				infile: path
				}
		}
	}

	type opt = {
		inspect: boolean
		quiet: boolean
		}
	const {inspect, quiet} = getOptions<opt>(hOptions, {
		inspect: false,
		quiet: false
		})

	if (inspect && !quiet) {
		LOG("procOneFile(): inspect is set")
	}

	const op = handler.op
	if (!quiet) {
		prelog(op, path)
	}

	try {
		timer.timeTaken()    // --- this resets the timer
		const hResult = await handler.handleFile(path, hOptions)
		if (quiet) {
			// --- handler.handleFile() will have set infile key
			return hResult
		}

		const {success, notNeeded} = hResult
		postlog(success, notNeeded)
		if (success) {
			showOkResult(handler, path, hResult, hOptions)
		}
		else {
			showErrResult(handler, path, hResult, hOptions)
		}
		return hResult
	}

	catch (err) {
		showRejResult(handler, path, err, hOptions)
		return {
			success: false,
			stderr: getErrStr(err),
			infile: path
			}
	}
}

// ---------------------------------------------------------------------------

const showOkResult = (
		handler: CFileHandler,
		path: string,
		hResult: TExecResult,
		hOptions: hash = {}
		): void => {

	if (hResult.notNeeded) {
		return
	}
	const output = handler.getOutput(hResult)
	if (defined(output) && nonEmpty(output)) {
		DUMP(output, 'OUTPUT', {escape: false})
	}
	return
}

// ---------------------------------------------------------------------------

const showErrResult = (
		handler: CFileHandler,
		path: string,
		hResult: TExecResult,
		hOptions: hash = {}
		): void => {

	const output = handler.getOutput(hResult)
	if (output) {
		DUMP(output, 'OUTPUT')
	}
	return
}

// ---------------------------------------------------------------------------

const showRejResult = (
		handler: CFileHandler,
		path: string,
		reason: unknown,
		hOptions: hash = {}
		): void => {

	DUMP(reason, 'ERROR')
	return
}

