class CFileRemover extends CFileHandler {

	get op() {
		return 'doRemoveFile'
	}

	override async needed(path: string): AutoPromise<boolean> {
		return await exists(path)
	}

	async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		await Deno.remove(path)
		return {
			success: true
			}
	}
}

export const doRemoveFile = new CFileRemover()

// ---------------------------------------------------------------------------

class CTsFileRemover extends CFileHandler {

	get op() {
		return 'doRemoveTsFile'
	}

	override async needed(
			path: string
			): AutoPromise<boolean> {

		if (!await exists(path)) {
			return false
		}
		const civetPath = withExt(path, '.civet')
		return await exists(civetPath)
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		assert((fileExt(path) === '.ts'), `Not a TypeScript file: ${path}`)
		await Deno.remove(path)
		return {
			success: true
			}
	}
}

export const doRemoveTsFile = new CTsFileRemover()

// ---------------------------------------------------------------------------

export const isInstalled = (scriptName: string): boolean => {

	const homeDir = Deno.env.get("HOME") ?? Deno.env.get("USERPROFILE") ?? ""
	const ext = (Deno.build.os === "windows") ? ".cmd" : ""
	const path = `${homeDir}/.deno/bin/${scriptName}${ext}`
	return existsSync(path) && Deno.statSync(path).isFile
}

// ---------------------------------------------------------------------------

export const getCmdName = (
		path: string,
		hOptions: hash
		): string => {

	if (('name' in hOptions) && (typeof hOptions.name === 'string')) {
		return hOptions.name as string
	}
	else {
		return parsePath(path).stub.replaceAll('.', '_')
	}
}

// ---------------------------------------------------------------------------

class CCmdInstaller extends CFileHandler {

	get op() {
		return 'doInstallCmd'
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		assert((fileExt(path) === '.ts'), `Not a TypeScript file: ${path}`)
		const name = getCmdName(path, hOptions)

		return await execCmd('deno', [
			'install',
			'--global',
			'--force',
			'--config', 'deno.json',
			'-A',
			'--name', name,
			path
			])
	}
}

export const doInstallCmd = new CCmdInstaller()

// ---------------------------------------------------------------------------

class CCmdUninstaller extends CFileHandler {

	get op() {
		return 'doUninstallCmd'
	}

	override async needed(
			path: string,
			hOptions: hash = {}
			) {
		const name = getCmdName(path, hOptions)
		return isInstalled(name)
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const name = getCmdName(path, hOptions)
		return await execCmd('deno', [
			'uninstall',
			'-g',
			name
			])
	}
}

export const doUninstallCmd = new CCmdUninstaller()

// ---------------------------------------------------------------------------

class CFileRunner extends CFileHandler {

	get op() {
		return 'doRun'
	}

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		type opt = {
			inspect: boolean
			label: (string | undefined)
			}
		const {inspect, label} = getOptions<opt>(hOptions, {
			inspect: false,
			label: undef
			})

		assert((fileExt(path) === '.ts'), "Not a TypeScript file")

		const hResult = await execCmd('deno', [
			'run',
			'-A',
			...(inspect ? ['--inspect-brk'] : []),
			path
			], hOptions)
		return hResult
	}
}

export const doRun = new CFileRunner()

